#!/usr/bin/env node
'use strict';
/* JAH Interview Q&A Expert AI engine — interviews-qa-expert-ai.
   Answers interview questions from the expert Q&A bank by token + tag scoring.
   Property of Justin Addam Higgins (JAH). Deterministic: same query, same answer. */
const BANK = [{"qid": "JAH-INTAI-000001", "q": "How should I answer 'tell me about yourself'?", "tags": ["behavioral", "opening", "introduction", "about yourself"], "a": "Use the Present-Past-Future structure in ninety seconds. Start with your current role and one headline achievement, rewind briefly through the experience that built toward this role, then land on why this specific job is the next step. End with forward momentum. Keep it a trailer, not the autobiography: enough to make them want the full story later. Never recite the resume chronologically."}, {"qid": "JAH-INTAI-000002", "q": "What is the best way to answer the weakness question?", "tags": ["behavioral", "weakness", "greatest weakness"], "a": "Name a real weakness, then spend most of your time on the system you built to manage it: the checklist, the calendar block, the peer review habit. The weakness is the setup; the management plan is the answer. Never use a disguised strength, interviewers have heard them all, and never name a weakness that is core to the job you are applying for."}, {"qid": "JAH-INTAI-000003", "q": "How do I talk about a failure in an interview?", "tags": ["behavioral", "failure", "mistake"], "a": "Use STAR with the failure as the situation. Describe what you tried, where it broke, what you did next, and the specific process change that came out of it. Own it plainly with no blame and no minimizing. End with the lesson as a durable rule you still follow. Interviewers distrust candidates who cannot name a real failure; it reads as evasion."}, {"qid": "JAH-INTAI-000004", "q": "How should I handle questions about conflict with coworkers?", "tags": ["behavioral", "conflict", "coworker", "disagreement"], "a": "Frame it as a disagreement about the work, never about the person. Describe the differing approaches, the direct conversation where you listened, and the resolution or escalation that followed. Show the working relationship afterward. Never badmouth the coworker, even subtly; the interviewer is imagining you describing them someday."}, {"qid": "JAH-INTAI-000005", "q": "How do I answer 'why do you want this job'?", "tags": ["behavioral", "why this job", "motivation", "fit"], "a": "Connect three threads: what the company is doing that genuinely interests you, what the role needs that you have actually done, and where it takes your career next. Specifics prove you researched; trajectory proves you will stay. Generic flattery fails. The hidden question is retention, so articulate the fit."}, {"qid": "JAH-INTAI-000006", "q": "How do I explain a REST API to a non-technical interviewer?", "tags": ["technical", "rest api", "communication", "explain"], "a": "Use the restaurant analogy: the menu is the API documentation, the waiter is the API, the kitchen is the server. Map GET to asking for a menu item and POST to placing an order; status codes are the waiter telling you the kitchen is out of something. Then check their understanding. Watch for jargon leakage: every unexplained term is a small failure of the exercise."}, {"qid": "JAH-INTAI-000007", "q": "What is the right process for debugging a production issue?", "tags": ["technical", "debugging", "production", "incident"], "a": "Protect the user first: triage, mitigate, or roll back before root-causing. Then walk the evidence chain: logs, metrics, recent deploys, bisecting the change to find the culprit. Fix, verify, and close with a postmortem plus a guardrail so it cannot recur. Never cowboy-debug on live systems without a safety net."}, {"qid": "JAH-INTAI-000008", "q": "SQL or NoSQL: how do I choose in an interview?", "tags": ["technical", "sql", "nosql", "database", "architecture"], "a": "Show the decision framework, not tribal loyalty. Choose relational when the data is structured, relationships matter, and consistency is critical. Choose document or key-value when the shape varies and horizontal scale dominates. Name the axes: schema stability, query patterns, consistency needs, operational scale. Then say when you would switch."}, {"qid": "JAH-INTAI-000009", "q": "How do I describe a CI/CD pipeline?", "tags": ["technical", "cicd", "pipeline", "devops", "deployment"], "a": "Walk the path from commit to production: lint and unit tests on pull request, integration tests on merge, staging deploy, smoke tests, then production with canary or blue-green deployment. Name the rollback plan, because every pipeline needs one. Mention deploy dashboards and alerts; a pipeline without monitoring is a hope, not a process."}, {"qid": "JAH-INTAI-000010", "q": "How should I talk about technical debt?", "tags": ["technical", "technical debt", "legacy"], "a": "Show triage thinking: distinguish debt that charges interest on every change from debt sitting quietly in stable corners. Schedule high-interest payoff like a feature, and translate the cost into velocity so product understands the budget ask. Document and defer the low-interest kind. Never demand a full rewrite and never ignore debt entirely."}, {"qid": "JAH-INTAI-000011", "q": "How do I answer situational questions about tight deadlines?", "tags": ["situational", "deadline", "pressure", "changing requirements"], "a": "Re-anchor on the real goal, renegotiate scope explicitly, and get sign-off on the tradeoff instead of silently crunching. Propose what can shrink, execute visibly with short check-ins, and treat heroics as a last resort, not a plan. Silent overtime as the default answer predicts burnout, not delivery."}, {"qid": "JAH-INTAI-000012", "q": "What if I disagree with my manager in a scenario question?", "tags": ["situational", "disagree", "manager", "dissent"], "a": "Raise it privately with evidence and alternatives, and listen fully because you might be wrong. Once a decision is made, commit publicly even if you lost the argument: disagree and commit. Never go over their head and never sulk afterward. The interviewer is checking both courage and loyalty."}, {"qid": "JAH-INTAI-000013", "q": "How do I show I can learn new technology quickly?", "tags": ["situational", "learning", "new technology", "ramp up"], "a": "Describe your learning system with a real example: build a small real project in week one, read the canonical guide, learn the community idioms, and get code reviewed by someone experienced. Set time-boxed milestones. A method with proof beats claiming you just pick things up, which sounds like luck."}, {"qid": "JAH-INTAI-000014", "q": "How do I answer the angry customer scenario?", "tags": ["situational", "angry customer", "support", "de-escalation"], "a": "Listen fully before responding, acknowledge the emotion, and repeat the issue back to prove you heard it. Apologize for the experience, then move to concrete next steps with a timeline, and follow up afterward. Never argue facts while someone is emotional: regulation before resolution."}, {"qid": "JAH-INTAI-000015", "q": "How do I demonstrate leading without authority?", "tags": ["leadership", "lead", "influence", "without authority"], "a": "Show the mechanics of influence: writing the clear proposal, doing the early legwork yourself, finding stakeholders' real incentives, and making the decision easy. Influence is built before it is spent. Give an example where people followed because the idea was good and the work was shared, not because of a title."}, {"qid": "JAH-INTAI-000016", "q": "What is the best structure for giving difficult feedback?", "tags": ["leadership", "feedback", "difficult conversation", "management"], "a": "Use SBI: situation, behavior, impact, then the request. Be specific and prompt, always in private, and pair the feedback with a path forward plus follow-up. It is a conversation starter, not a verdict. Never sandwich praise around criticism to soften it and never delay hard conversations."}, {"qid": "JAH-INTAI-000017", "q": "How do I answer prioritization questions as a leader?", "tags": ["leadership", "prioritization", "competing projects", "strategy"], "a": "Apply the framework openly: impact, effort, urgency, and strategic fit. Make tradeoffs explicit, name what is being deprioritized and why, and revisit on a cadence. Stakeholders accept no when they understand the yes. Never claim you would do everything; that predicts nothing delivered well."}, {"qid": "JAH-INTAI-000018", "q": "How do I handle the salary expectation question?", "tags": ["compensation", "salary", "negotiation", "pay"], "a": "Give a researched range, not a single number, anchored to market data for the role, level, and location. State the range confidently and let them position within it. Deflecting forever frustrates; answering with a range shows preparation. Keep the tone collaborative: you are solving the fit together, not haggling."}, {"qid": "JAH-INTAI-000019", "q": "What questions should I ask the interviewer?", "tags": ["questions to ask", "interviewer", "reverse interview"], "a": "Ask about the actual work: what does success look like in six months, what is the hardest problem the team faces, and how are decisions made here. Ask your future manager what they value in top performers. Avoid questions answered by the website. Good questions prove you are evaluating them too, which strong candidates do."}, {"qid": "JAH-INTAI-000020", "q": "How do I follow up after the interview?", "tags": ["follow up", "thank you", "after interview"], "a": "Send a brief thank-you within twenty-four hours: one specific thing you discussed, one reason you are excited about the role, and no groveling. If they gave a timeline, respect it; if it passes, one polite nudge is fine. Keep every follow-up short. The interview is the product; the follow-up is the receipt."}];
const STOP = new Set(["a", "about", "after", "again", "all", "am", "an", "and", "any", "are", "as", "at", "be", "before", "between", "both", "by", "can", "could", "do", "down", "each", "few", "for", "from", "had", "has", "have", "here", "how", "i", "if", "in", "into", "is", "it", "just", "me", "more", "most", "my", "now", "of", "off", "on", "once", "only", "or", "other", "out", "over", "own", "s", "same", "should", "so", "some", "such", "t", "than", "that", "the", "their", "them", "then", "there", "these", "this", "those", "to", "too", "up", "very", "vs", "was", "were", "what", "when", "where", "which", "who", "whom", "will", "with", "would", "you", "your"]);
function tokens(s){
  return s.toLowerCase().split(/[^a-z0-9]+/).filter(function(w){return w.length>1 && !STOP.has(w);});
}
function answer(query){
  var ql = String(query||'').toLowerCase();
  var qt = tokens(ql);
  var best = null, bestScore = 0, scored = [];
  for(var i=0;i<BANK.length;i++){
    var e = BANK[i];
    var qTok = {}, tagTok = {}, k;
    tokens(e.q).forEach(function(w){qTok[w]=1;});
    e.tags.forEach(function(tag){tokens(tag).forEach(function(w){tagTok[w]=1;});});
    var s = 0;
    for(k=0;k<qt.length;k++){
      var t = qt[k];
      if(tagTok[t]) s += 3; else if(qTok[t]) s += 1;
    }
    e.tags.forEach(function(tag){ if(tag.length>2 && ql.indexOf(tag)>=0) s += 2; });
    scored.push({e:e,s:s});
    if(s > bestScore){ bestScore = s; best = e; }
  }
  if(!best || bestScore < 2){
    scored.sort(function(a,b){return b.s-a.s;});
    return {qid:null, score:bestScore,
      answer:'No confident match in the expert bank. Try rephrasing with interview terms like: weakness, salary, STAR, conflict, debugging, SQL.',
      suggestions:scored.slice(0,3).map(function(x){return {qid:x.e.qid, question:x.e.q, score:x.s};})};
  }
  return {qid:best.qid, question:best.q, score:bestScore, answer:best.a};
}
if(typeof module!=='undefined' && require.main===module){
  var q = process.argv.slice(2).join(' ');
  console.log(JSON.stringify(answer(q)));
}
if(typeof module!=='undefined' && module.exports){ module.exports = {answer:answer, BANK:BANK}; }

