    var s = 0;
    for(k=0;k<qt.length;k++){
      var t = qt[k];
      if(tagTok[t]) s += 3; else if(qTok[t]) s += 1;
    }
    e.tags.forEach(function(tag){ if(tag.length>2 && ql.indexOf(tag)>=0) s += 2; });
    scored.push({e:e,s:s});
